"version": "1.0.0",
"contentHash": "3ea7f0b2752a7b7ec9e64b36273ba3d461c9f12df2257206c8a7bd0fbe65729e",
"status": "mapped",
"reviewStatus": "machine_adjudicated",
"assessedIds": [
"math:function-composition-iteration"
],
